create table public.recurring_bills (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, category_id text not null, name text not null, amount_minor bigint not null check(amount_minor>0), due_day integer not null check(due_day between 1 and 31), payment_method text, is_avoidable boolean not null default false, is_active boolean not null default true, created_at timestamptz not null default now());
create table public.credit_cards (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, limit_minor bigint check(limit_minor>=0), closing_day integer check(closing_day between 1 and 31), due_day integer check(due_day between 1 and 31), is_active boolean not null default true, created_at timestamptz not null default now());
create table public.card_purchases (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, card_id uuid not null references public.credit_cards(id) on delete cascade, category_id text not null, description text, total_minor bigint not null check(total_minor>0), purchased_on date not null, installment_count integer not null default 1 check(installment_count>=1), is_avoidable boolean not null default false, created_at timestamptz not null default now());
create table public.card_installments (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, purchase_id uuid not null references public.card_purchases(id) on delete cascade, installment_number integer not null check(installment_number>=1), amount_minor bigint not null check(amount_minor>0), billing_month date not null, paid_at timestamptz, unique(purchase_id,installment_number));
create table public.debts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, original_minor bigint not null check(original_minor>0), outstanding_minor bigint not null check(outstanding_minor>=0), installment_minor bigint check(installment_minor>=0), installments_remaining integer check(installments_remaining>=0), expected_end date, is_active boolean not null default true, created_at timestamptz not null default now());
alter table public.recurring_bills enable row level security; alter table public.credit_cards enable row level security; alter table public.card_purchases enable row level security; alter table public.card_installments enable row level security; alter table public.debts enable row level security;
create policy recurring_bills_own on public.recurring_bills for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id); create policy credit_cards_own on public.credit_cards for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id); create policy card_purchases_own on public.card_purchases for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id); create policy card_installments_own on public.card_installments for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id); create policy debts_own on public.debts for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create index recurring_bills_user_idx on public.recurring_bills(user_id); create index credit_cards_user_idx on public.credit_cards(user_id); create index card_purchases_user_date_idx on public.card_purchases(user_id,purchased_on desc); create index card_installments_user_month_idx on public.card_installments(user_id,billing_month); create index debts_user_idx on public.debts(user_id);
